#!/bin/sh
#
# TCP reassembly: segments delivered out of order (plus a retransmission)
# must be put back into sequence order in the reconstructed flow file.
# The pcap is generated by gen_test_pcaps.py.
#

. $srcdir/test-subs.sh

DMPFILE=$DMPDIR/reassembly-outoforder.pcap

[ -r "$DMPFILE" ] || { echo "$DMPFILE not found" ; exit 77 ; }

OUT=out-reassembly

rm -rf $OUT

cmd "$TCPFLOW -o $OUT -r $DMPFILE"

FLOW=$OUT/010.000.000.001.40001-010.000.000.002.09000

# The shuffled segments must reassemble into the original byte sequence.
checkmd5 "$FLOW" "c1bcb570d7c6b0cea4af0c72299a1529" "33"

content=`cat "$FLOW"`
if [ "$content" != "AAA-1-BBB-2-CCC-3-DDD-4-EEE-5-END" ] ; then
  echo "failure: reassembled stream out of order:"
  echo "$content"
  exit 1
fi

# Only the client->server direction carries data (plus the report); the
# empty reverse direction must not produce a flow data file.
count=`ls "$OUT" | grep -v '^report.xml$' | wc -l | tr -d ' '`
if [ "$count" != "1" ] ; then
  echo "failure: expected 1 data flow file, got $count"
  ls "$OUT"
  exit 1
fi

rm -rf $OUT
exit 0
